// generated by gemini-3.5-flash-lite for PR #5824 (round 0): cbor_roundtrip_verification
// intent: Probes roundtrip consistency: serializing an array of numbers to CBOR and parsing it back.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json original = nlohmann::json::array();
        for (int i = 0; i < 100; ++i) {
            original.push_back(i * 7 - 350);
        }
        std::vector<std::uint8_t> cbor;
        nlohmann::to_cbor(original, cbor);
        nlohmann::json parsed = nlohmann::json::from_cbor(cbor);
        std::cout << "roundtrip_equal: " << (original == parsed) << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
